const HDR = `.hdr{position:absolute;left:0;right:0;top:0;display:flex;align-items:center;justify-content:space-between;z-index:4}.hdr .hc{position:absolute;left:50%;transform:translateX(-50%)}.mhdr{position:absolute;left:0;right:0;top:0;padding:14px 16px;display:flex;align-items:center;justify-content:space-between;z-index:4}.tabs{display:flex;gap:28px;font-weight:500;font-size:15px}.tabs span{padding:6px 0;border-bottom:2px solid transparent;color:var(--ink2)}.tabs span.on{border-color:var(--ink);color:var(--ink)}.navy{color:var(--ink);--ink:#ECEEF8;--ink2:#C3C9DC;--muted:#98A2BA;--line:rgba(255,255,255,.14);--card2:rgba(255,255,255,.07);--card:rgba(255,255,255,.1);--btn:#F5B69E;--btnfg:#1A1C29;--soft:rgba(141,185,240,.28)}`;
const hdr = (t, center = "", pad = "22px 32px") => `<header class="hdr" style="padding:${pad}"><div>${logo(t, 40)}</div><div class="hc">${center}</div><div>${tools(t, 2)}</div></header>`;
const mhdr = (t) => `<header class="mhdr"><div>${logo(t, 30, false)}</div>${toolsMobile(t)}</header>`;
const fmt = (n) => n.toLocaleString("en-IN");
const tabs = (on = -1) => `<nav class="tabs">${["Practice", "Study", "AI Mentor", "Review", "Analytics", "Battles"].map((l, i) => `<span class="${i === on ? "on" : ""}">${l}</span>`).join("")}</nav>`;
const dockBar = (on = 0) => `<nav class="dock">${[["Home", "home"], ["Practice", "test"], ["Study", "book"], ["Mentor", "spark"], ["Review", "layers"], ["Analytics", "chart"]].map(([l, n], i) => `<span class="di ${i === on ? "on" : ""}">${ic(n, 18)}${i === on ? l : ""}</span>`).join("")}</nav>`;
const DOCK = `.dock{position:absolute;left:50%;bottom:22px;transform:translateX(-50%);display:flex;gap:4px;padding:8px;border-radius:999px;background:var(--glass);border:1px solid var(--line);backdrop-filter:blur(18px);box-shadow:var(--shadow);z-index:5}.dock .di{display:flex;align-items:center;gap:8px;padding:12px 18px;border-radius:99px;font-weight:600;color:var(--ink2);font-size:14px}.dock .di.on{background:var(--powder);color:#1A1C29}`;
const polar = (cx, cy, r, deg) => [cx + r * Math.cos((deg * Math.PI) / 180), cy + r * Math.sin((deg * Math.PI) / 180)];
const arc = (cx, cy, r, a0, a1) => { const [x0, y0] = polar(cx, cy, r, a0), [x1, y1] = polar(cx, cy, r, a1); return `M ${x0} ${y0} A ${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${x1} ${y1}`; };

/* ---------- 11 Score Gauge: one predicted number, and what moves it ---------- */
export const gauge = (w, score = 58, target = 70) => {
  const cx = w / 2, cy = w / 2 + 6, r = w / 2 - 22, sw = Math.round(w / 17);
  const bands = [[0, 40, "var(--hot)"], [40, 60, "rgba(141,185,240,.45)"], [60, 80, "rgba(141,185,240,.8)"], [80, 100, "#3A6FB8"]];
  const ang = (v) => 180 + v * 1.8;
  const [mx, my] = polar(cx, cy, r, ang(score)), [tx0, ty0] = polar(cx, cy, r - sw, ang(target)), [tx1, ty1] = polar(cx, cy, r + sw, ang(target));
  return `<svg width="${w}" height="${w / 2 + 40}" viewBox="0 0 ${w} ${w / 2 + 40}">${bands.map(([a, b, c]) => `<path d="${arc(cx, cy, r, ang(a) + (a ? 1 : 0), ang(b) - 1)}" fill="none" stroke="${c}" stroke-width="${sw}" stroke-linecap="round"/>`).join("")}<line x1="${tx0}" y1="${ty0}" x2="${tx1}" y2="${ty1}" stroke="var(--ink)" stroke-width="3" stroke-linecap="round"/><circle cx="${mx}" cy="${my}" r="${sw * 0.78}" fill="#fff" stroke="#1A1C29" stroke-width="5"/></svg>`;
};
