/* ---------- 16 Subject Radar: your shape against the target ---------- */
export const radar = (w, vals, labels, target = 70) => {
  const cx = w / 2, cy = w / 2, R = w / 2 - 70, n = vals.length;
  const pt = (i, v) => polar(cx, cy, (R * v) / 100, -90 + (360 / n) * i);
  const poly = (f) => vals.map((v, i) => pt(i, f(v)).join(",")).join(" ");
  return `<svg width="${w}" height="${w}" viewBox="0 0 ${w} ${w}">${[25, 50, 75, 100].map((l) => `<polygon points="${vals.map((_, i) => pt(i, l).join(",")).join(" ")}" fill="none" stroke="var(--line)" stroke-width="1.5"/>`).join("")}${vals.map((_, i) => `<line x1="${cx}" y1="${cy}" x2="${pt(i, 100)[0]}" y2="${pt(i, 100)[1]}" stroke="var(--line)"/>`).join("")}<polygon points="${poly(() => target)}" fill="none" stroke="var(--peach-d)" stroke-width="2" stroke-dasharray="6 6"/><polygon points="${poly((v) => v)}" fill="rgba(141,185,240,.5)" stroke="var(--powder-d)" stroke-width="3" stroke-linejoin="round"/>${vals.map((v, i) => `<circle cx="${pt(i, v)[0]}" cy="${pt(i, v)[1]}" r="6" fill="var(--bg)" stroke="var(--powder-d)" stroke-width="3"/>`).join("")}${labels.map((l, i) => { const [x, y] = polar(cx, cy, R + 40, -90 + (360 / n) * i); return `<text x="${x}" y="${y - 2}" text-anchor="middle" font-family="Outfit" font-size="15" font-weight="600" fill="var(--ink)">${l}</text><text x="${x}" y="${y + 18}" text-anchor="middle" font-family="Outfit" font-size="14" fill="var(--muted)">${vals[i]}%</text>`; }).join("")}</svg>`;
};
